-- Netherlands: ES/DE/FR milestone translations (real translations
-- replacing the scaffolder's drafts/ stub). INSERT OR IGNORE, idempotent.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-2017', 'es', 'Facturación electrónica B2G obligatoria para el gobierno central', 'Al transponer la Directiva UE 2014/55/EU, los Países Bajos exigieron que todos los proveedores del gobierno central emitieran facturas electrónicas estructuradas desde el 1 de enero de 2017, con la obligación de que todos los organismos públicos pudieran recibirlas. Logius gestiona la infraestructura central, incluyendo Digipoort y el Punto de Acceso Peppol del Gobierno Central (Rijksoverheid).', '["Contexto histórico — no requiere acción"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-2017', 'de', 'B2G-E-Rechnungspflicht für die Zentralregierung', 'In Umsetzung der EU-Richtlinie 2014/55/EU verlangten die Niederlande ab dem 1. Januar 2017 von allen Lieferanten der Zentralregierung die Ausstellung strukturierter elektronischer Rechnungen, wobei alle öffentlichen Stellen zu deren Empfang in der Lage sein mussten. Logius betreibt die zentrale Infrastruktur, einschließlich Digipoort und des Rijksoverheid-Peppol-Zugangspunkts.', '["Historischer Kontext — keine Maßnahme erforderlich"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-2017', 'fr', 'Facturation électronique B2G obligatoire pour l''administration centrale', 'En transposant la directive UE 2014/55/EU, les Pays-Bas ont exigé que tous les fournisseurs de l''administration centrale émettent des factures électroniques structurées à compter du 1er janvier 2017, tous les organismes publics devant être en mesure de les recevoir. Logius exploite l''infrastructure centrale, y compris Digipoort et le point d''accès Peppol du gouvernement central (Rijksoverheid).', '["Contexte historique — aucune action requise"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-subcentral-2019', 'es', 'Facturación electrónica B2G ampliada a todo el sector público (vigente desde abril de 2019)', 'Desde el 18 de abril de 2019, el mandato de facturación electrónica B2G se amplió más allá del gobierno central para abarcar a todos los organismos públicos neerlandeses — municipios, provincias, autoridades hídricas y otras entidades gubernamentales. Las facturas se envían a través de la red Peppol (BIS 3.0 / SI-UBL 2.0), la pasarela directa Digipoort para proveedores de gran volumen, o el Portal de Proveedores del Gobierno para el envío manual de bajo volumen. La Autoridad Peppol de los Países Bajos (antes SimplerInvoicing) rige la implementación nacional de Peppol bajo el Ministerio del Interior.', '["Confirme que su facturación al sector público neerlandés se realiza mediante Peppol, Digipoort o el Portal de Proveedores del Gobierno", "Verifique el cumplimiento de SI-UBL 2.0 / Peppol BIS 3.0 en cualquier contrato con el gobierno neerlandés"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-subcentral-2019', 'de', 'B2G-E-Rechnung auf den gesamten öffentlichen Sektor ausgeweitet (in Kraft seit April 2019)', 'Ab dem 18. April 2019 wurde die B2G-E-Rechnungspflicht über die Zentralregierung hinaus auf alle niederländischen öffentlichen Stellen ausgeweitet — Gemeinden, Provinzen, Wasserverbände und andere Regierungseinrichtungen. Rechnungen werden über das Peppol-Netzwerk (BIS 3.0 / SI-UBL 2.0), das Digipoort-Direktgateway für Lieferanten mit hohem Volumen oder das Regierungslieferantenportal für die manuelle Einreichung bei geringem Volumen übermittelt. Die niederländische Peppol-Behörde (vormals SimplerInvoicing) regelt die nationale Peppol-Umsetzung unter dem Innenministerium.', '["Bestätigen Sie, dass Ihre Rechnungsstellung an den niederländischen öffentlichen Sektor über Peppol, Digipoort oder das Regierungslieferantenportal läuft", "Prüfen Sie die SI-UBL-2.0-/Peppol-BIS-3.0-Konformität bei niederländischen Regierungsaufträgen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-subcentral-2019', 'fr', 'Facturation électronique B2G étendue à tout le secteur public (en vigueur depuis avril 2019)', 'À compter du 18 avril 2019, l''obligation de facturation électronique B2G s''est étendue au-delà de l''administration centrale à tous les organismes publics néerlandais — communes, provinces, autorités des eaux et autres entités gouvernementales. Les factures sont transmises via le réseau Peppol (BIS 3.0 / SI-UBL 2.0), la passerelle directe Digipoort pour les fournisseurs à fort volume, ou le portail fournisseurs du gouvernement pour la saisie manuelle à faible volume. L''autorité Peppol des Pays-Bas (anciennement SimplerInvoicing) régit la mise en œuvre nationale de Peppol sous l''égide du ministère de l''Intérieur.', '["Confirmez que votre facturation au secteur public néerlandais transite par Peppol, Digipoort ou le portail fournisseurs du gouvernement", "Vérifiez la conformité SI-UBL 2.0 / Peppol BIS 3.0 pour tout contrat avec le gouvernement néerlandais"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2b-voluntary', 'es', 'La facturación electrónica B2B sigue siendo voluntaria, con alta adopción de Peppol', 'A diferencia de Bélgica, Francia, Alemania, Italia y Polonia, los Países Bajos han optado por un enfoque impulsado por el mercado en lugar de un mandato para la facturación electrónica B2B: las empresas pueden intercambiar facturas electrónicas estructuradas si el destinatario está de acuerdo, y no existe un régimen nacional de compensación o de reporte en tiempo real. Aun así, la adopción es alta — la mayoría del software neerlandés de ERP y contabilidad admite de forma nativa Peppol BIS 3.0 / SI-UBL 2.0, y las grandes contrapartes exigen cada vez más su uso como condición de contratación.', '["No se requiere ninguna acción B2B nacional, pero confirme contractualmente las expectativas de Peppol de sus contrapartes", "Considere la adopción voluntaria de Peppol dada su alta penetración entre los socios comerciales neerlandeses"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2b-voluntary', 'de', 'B2B-E-Rechnung bleibt freiwillig, bei hoher Peppol-Verbreitung', 'Anders als Belgien, Frankreich, Deutschland, Italien und Polen haben die Niederlande bei der B2B-E-Rechnung einen marktgetriebenen Ansatz statt einer Pflicht gewählt: Unternehmen dürfen strukturierte E-Rechnungen austauschen, sofern der Empfänger zustimmt, und es gibt kein nationales Clearance- oder Echtzeit-Meldesystem. Die Verbreitung ist dennoch hoch — die meiste niederländische ERP- und Buchhaltungssoftware unterstützt Peppol BIS 3.0 / SI-UBL 2.0 nativ, und wichtige Geschäftspartner verlangen es zunehmend als Beschaffungsbedingung.', '["Keine inländische B2B-Maßnahme erforderlich, aber vertragliche Peppol-Erwartungen der Geschäftspartner klären", "Angesichts der hohen Marktdurchdringung eine freiwillige Peppol-Einführung erwägen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2b-voluntary', 'fr', 'La facturation électronique B2B reste volontaire, avec une forte adoption de Peppol', 'Contrairement à la Belgique, la France, l''Allemagne, l''Italie et la Pologne, les Pays-Bas ont opté pour une approche guidée par le marché plutôt qu''une obligation en matière de facturation électronique B2B : les entreprises peuvent échanger des factures électroniques structurées si le destinataire y consent, et il n''existe aucun régime national de validation préalable ou de déclaration en temps réel. L''adoption n''en demeure pas moins élevée — la plupart des logiciels ERP et comptables néerlandais prennent nativement en charge Peppol BIS 3.0 / SI-UBL 2.0, et les principaux partenaires commerciaux l''exigent de plus en plus comme condition d''achat.', '["Aucune action B2B nationale requise, mais confirmez contractuellement les attentes Peppol de vos partenaires", "Envisagez l''adoption volontaire de Peppol compte tenu de sa forte pénétration parmi les partenaires commerciaux néerlandais"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-eyreport-2026', 'es', 'El gobierno señala un probable mandato B2B nacional, escalonado entre 2030 y 2032 (informe consultivo, marzo de 2026)', 'El 10 de marzo de 2026, el Secretario de Estado de Hacienda neerlandés presentó al Parlamento una respuesta formal sobre la implementación del pilar de facturación electrónica del IVA en la Era Digital (ViDA) de la UE, acompañada de un informe consultivo externo que evalúa dos escenarios: ViDA-A (solo B2B transfronterizo) frente a ViDA-B (extensión al B2B nacional). El informe recomienda ViDA-B sobre una infraestructura Peppol obligatoria, escalonada entre 2030 y 2032, citando como precedente la reducción de la brecha del IVA en Italia. Se espera una respuesta política formal durante el verano de 2026, con una consulta pública sobre el anteproyecto de ley prevista para el cuarto trimestre de 2026 — aún no se ha adoptado ninguna legislación.', '["Siga la respuesta política del verano de 2026 y la consulta prevista sobre el anteproyecto de ley en el cuarto trimestre de 2026", "Si el B2B nacional pasa a ser obligatorio, prevea que Peppol BIS 3.0 sea probablemente el canal designado, dado el precedente del B2G"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-eyreport-2026', 'de', 'Regierung signalisiert wahrscheinliche inländische B2B-Pflicht, gestaffelt 2030–2032 (Gutachten, März 2026)', 'Am 10. März 2026 übermittelte der niederländische Staatssekretär für Finanzen dem Parlament eine formelle Antwort zur Umsetzung der E-Rechnungs-Säule der EU-Initiative VAT in the Digital Age (ViDA), begleitet von einem externen Gutachten, das zwei Szenarien bewertet: ViDA-A (nur grenzüberschreitendes B2B) versus ViDA-B (Ausweitung auf inländisches B2B). Das Gutachten empfiehlt ViDA-B auf verpflichtender Peppol-Infrastruktur, gestaffelt zwischen 2030 und 2032, unter Verweis auf die Reduzierung der Umsatzsteuerlücke in Italien als Präzedenzfall. Eine formelle politische Antwort wird für den Sommer 2026 erwartet, eine öffentliche Konsultation zum Gesetzentwurf ist für das vierte Quartal 2026 geplant — es wurde noch keine Gesetzgebung verabschiedet.', '["Die politische Antwort im Sommer 2026 und die geplante Konsultation zum Gesetzentwurf im vierten Quartal 2026 beobachten", "Falls das inländische B2B verpflichtend wird, ist angesichts des B2G-Präzedenzfalls Peppol BIS 3.0 als wahrscheinlicher vorgesehener Kanal zu erwarten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-eyreport-2026', 'fr', 'Le gouvernement signale une probable obligation B2B nationale, échelonnée entre 2030 et 2032 (rapport consultatif, mars 2026)', 'Le 10 mars 2026, le secrétaire d''État néerlandais aux Finances a transmis au Parlement une réponse formelle sur la mise en œuvre du volet facturation électronique de l''initiative européenne TVA à l''ère numérique (ViDA), accompagnée d''un rapport consultatif externe évaluant deux scénarios : ViDA-A (B2B transfrontalier uniquement) contre ViDA-B (extension au B2B national). Le rapport recommande ViDA-B sur une infrastructure Peppol obligatoire, échelonnée entre 2030 et 2032, citant en précédent la réduction de l''écart de TVA en Italie. Une réponse politique formelle est attendue durant l''été 2026, avec une consultation publique sur le projet de loi prévue pour le quatrième trimestre 2026 — aucune législation n''a encore été adoptée.', '["Suivre la réponse politique de l''été 2026 et la consultation prévue sur le projet de loi au quatrième trimestre 2026", "Si le B2B national devient obligatoire, s''attendre à ce que Peppol BIS 3.0 soit probablement le canal désigné, compte tenu du précédent B2G"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-vida-2030', 'es', 'La facturación electrónica B2B transfronteriza de ViDA y el reporte digital se vuelven obligatorios (legislación de la UE confirmada)', 'Desde el 1 de julio de 2030, en virtud de la Directiva (UE) 2025/516 del Consejo, la facturación electrónica estructurada y el reporte digital pasan a ser obligatorios para todas las entregas B2B intracomunitarias — un suelo firme de derecho de la UE, independientemente de lo que decidan los Países Bajos sobre el B2B nacional. Si el gobierno avanza con la extensión nacional ViDA-B recomendada en marzo de 2026, prácticamente todas las empresas registradas a efectos de IVA en los Países Bajos acabarían intercambiando facturas electrónicas conforme a la norma EN 16931, probablemente a través de Peppol.', '["Prepárese para la facturación electrónica estructurada obligatoria en todo el comercio B2B intracomunitario desde mediados de 2030, con independencia del resultado del mandato nacional", "Siga por separado la decisión sobre el mandato nacional, ya que su alcance (y el escalonamiento 2030-2032) puede superar el mínimo del derecho de la UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-vida-2030', 'de', 'ViDA-grenzüberschreitende B2B-E-Rechnung und digitale Meldung werden verpflichtend (bestätigtes EU-Recht)', 'Ab dem 1. Juli 2030 werden gemäß der Richtlinie (EU) 2025/516 des Rates strukturierte E-Rechnungen und digitale Meldungen für alle innergemeinschaftlichen B2B-Lieferungen verpflichtend — eine feste EU-rechtliche Untergrenze, unabhängig davon, wie die Niederlande beim inländischen B2B entscheiden. Sollte die Regierung die im März 2026 empfohlene ViDA-B-Ausweitung auf das Inland umsetzen, würden praktisch alle umsatzsteuerregistrierten Unternehmen in den Niederlanden letztlich E-Rechnungen nach EN 16931 austauschen, höchstwahrscheinlich über Peppol.', '["Auf verpflichtende strukturierte E-Rechnungen für den gesamten innergemeinschaftlichen B2B-Handel ab Mitte 2030 vorbereiten, unabhängig vom Ausgang der inländischen Pflicht", "Die Entscheidung zur inländischen Pflicht separat verfolgen, da ihr Umfang (und die Staffelung 2030–2032) über das EU-rechtliche Minimum hinausgehen kann"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-vida-2030', 'fr', 'La facturation électronique B2B transfrontalière ViDA et la déclaration numérique deviennent obligatoires (droit de l''UE confirmé)', 'À compter du 1er juillet 2030, en vertu de la directive (UE) 2025/516 du Conseil, la facturation électronique structurée et la déclaration numérique deviennent obligatoires pour toutes les livraisons B2B intracommunautaires — un plancher ferme de droit de l''UE, quelle que soit la décision des Pays-Bas sur le B2B national. Si le gouvernement va de l''avant avec l''extension nationale ViDA-B recommandée en mars 2026, pratiquement toutes les entreprises assujetties à la TVA aux Pays-Bas échangeraient à terme des factures électroniques conformes à la norme EN 16931, probablement via Peppol.', '["Se préparer à la facturation électronique structurée obligatoire sur tout le commerce B2B intra-UE dès mi-2030, indépendamment de l''issue de l''obligation nationale", "Suivre séparément la décision relative à l''obligation nationale, car son périmètre (et l''échelonnement 2030-2032) peut dépasser le minimum imposé par le droit de l''UE"]');
